import time
import random

def construct():
    start_time = time.time()
    deadline = start_time + 55.0
    
    n = 17
    min_dist = 6
    max_size = 340
    
    # Precompute popcounts
    popcount = [0] * (1 << n)
    for i in range(1, 1 << n):
        popcount[i] = popcount[i >> 1] + (i & 1)
        
    # Generate candidate generator polynomials for the [17,9,d] QR code
    # The QR code of length 17 is generated by a degree 8 polynomial
    # dividing x^17 - 1.
    # Possible generators:
    g1 = (1 << 8) | (1 << 4) | (1 << 3) | (1 << 2) | 1  # x^8 + x^4 + x^3 + x^2 + 1
    g2 = (1 << 8) | (1 << 5) | (1 << 3) | (1 << 1) | 1  # x^8 + x^5 + x^3 + x + 1
    
    def generate_code(g):
        # g is an integer mask for the generator polynomial (degree 8)
        # The code consists of all a(x)g(x) mod (x^17 - 1) for a(x) in GF(2)^9
        # Since deg(a) <= 8 and deg(g) <= 8, deg(product) <= 16.
        # So no wrap-around needed for x^17.
        codewords = []
        for a in range(1 << 9):
            # Compute a(x) * g(x)
            # We can do this by shifting and XORing
            prod = 0
            for i in range(9):
                if (a >> i) & 1:
                    prod ^= (g << i)
            codewords.append(prod)
        return codewords

    best_initial = None
    for g in [g1, g2]:
        code = generate_code(g)
        # Check min distance
        min_d = 17
        for i in range(len(code)):
            for j in range(i+1, len(code)):
                d = popcount[code[i] ^ code[j]]
                if d < min_d:
                    min_d = d
                    if min_d < min_dist:
                        break
            if min_d < min_dist:
                break
        
        if min_d >= min_dist:
            best_initial = code
            break
        else:
            # Try to find a subcode of size 256 with min distance >= 6
            # The code has dimension 9. A subcode of dimension 8 has size 256.
            # We look for a non-zero vector u in GF(2)^9 such that
            # {c in code | dot(u, c) == 0} has min distance >= 6.
            found_subcode = False
            for u in range(1, 1 << 9):
                subcode = []
                for c in code:
                    # dot product in GF(2)
                    if popcount[u & c] % 2 == 0:
                        subcode.append(c)
                
                # Check min distance of subcode
                min_d_sub = 17
                for i in range(len(subcode)):
                    for j in range(i+1, len(subcode)):
                        d = popcount[subcode[i] ^ subcode[j]]
                        if d < min_d_sub:
                            min_d_sub = d
                            if min_d_sub < min_dist:
                                break
                    if min_d_sub < min_dist:
                        break
                
                if min_d_sub >= min_dist:
                    best_initial = subcode
                    found_subcode = True
                    break
            
            if found_subcode:
                break

    if best_initial is None:
        # Fallback: Greedy from 0
        best_initial = [0]
    else:
        # Ensure 0 is in the code? Linear codes contain 0.
        # The subcode search includes 0.
        pass

    current_cw = best_initial.copy()
    best_size = len(current_cw)
    
    # Greedy expansion
    # Create list of all candidates not in current_cw
    # To save memory, we can just iterate through all 2^17 numbers
    # and check if they are in the set.
    cw_set = set(current_cw)
    
    # Optimization: Precompute distances to current codewords?
    # No, just check on the fly.
    
    # Shuffle candidates for randomization
    candidates = list(range(1 << n))
    random.shuffle(candidates)
    
    def run_greedy_pass(order, current_codewords):
        codewords = current_codewords.copy()
        cw_set_local = set(codewords)
        
        for candidate in order:
            if time.time() > deadline - 2.0:
                break
            if candidate in cw_set_local:
                continue
            
            valid = True
            for cw in codewords:
                if popcount[candidate ^ cw] < min_dist:
                    valid = False
                    break
            if valid:
                codewords.append(candidate)
                cw_set_local.add(candidate)
        
        return codewords

    # Run one or more passes
    # Since we start with a good code, we might add a few words.
    # We can do a few random restarts of the greedy phase.
    
    best_codewords = current_cw
    
    while time.time() < deadline - 2.0:
        random.shuffle(candidates)
        current_cw = run_greedy_pass(candidates, best_codewords)
        
        if len(current_cw) > len(best_codewords):
            best_codewords = current_cw
            
            if len(best_codewords) >= max_size:
                break

    return best_codewords
